    data = json.load(f)

# Find all elements that contain TIPS
def find_tips(element, path=''):
    results = []
    if isinstance(element, dict):
        for key, value in element.items():
            if isinstance(value, str) and 'TIPS' in value:
                results.append((path + '.' + key, value))
            results.extend(find_tips(value, path + '.' + key))
